/*
 * A054098  Triangular array generated by its row sums: T(n,0)=1 for n >= 0,
 *          T(1,1)=2, T(n,k)=T(n,k-1)+d*r(n-k) for k=2,3,...,n, d=(-1)^(k+1),
 *          n >= 2, r(h)=sum of the numbers in row h of T.
 * https://oeis.org/A054098
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabl, eigen
 * Formula:   a(n) = T(row,col) where T(n,0)=1, T(1,1)=2, T(n,1)=sum of row
 *            n‑1, T(n,k)=T(n,k‑1)+(-1)^(k+1)*sum of row n‑k (k≥2). The
 *            sequence begins 1,1,2,1,3,2,1,6,3,4, …
 * Range:     u8 n <= 29, u16 n <= 52, u32 n <= 52, u64 n <= 52, u128 n <= 52,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stddef.h>

/* ------------------------------------------------------------------ */
/* Cache for the triangular array and its row sums                    */

static idx_t    *row_start = NULL;   /* first element index of each row   */
static seq_t    *row_sum   = NULL;   /* sum of each row                   */
static seq_t    *vals      = NULL;   /* flattened array of all rows       */
static size_t   rows      = 0;       /* number of rows stored             */
static idx_t    total_elems = 0;     /* total number of values stored     */
static size_t   vals_cap   = 0;       /* capacity of vals array            */
static size_t   row_cap    = 0;       /* capacity of row_start/row_sum arr */

/* ------------------------------------------------------------------ */
/* grow a sequence array, allocating in multiples of 2                */

static void grow_vals(size_t needed)
{
    if (needed > vals_cap) {
        vals_cap = needed > vals_cap ? needed : (vals_cap? 2*vals_cap : 16);
        vals = (seq_t*)realloc(vals, vals_cap * sizeof(seq_t));
    }
}

static void grow_rows(size_t needed)
{
    if (needed > row_cap) {
        row_cap = needed > row_cap ? needed : (row_cap? 2*row_cap : 16);
        row_start = (idx_t*)realloc(row_start, row_cap * sizeof(idx_t));
        row_sum   = (seq_t*)realloc(row_sum,   row_cap * sizeof(seq_t));
    }
}

/* ------------------------------------------------------------------ */
/* ensure rows up to "r_needed" (0‑based) have been generated          */

static void ensure_rows(idx_t n)
{
    /* Find row number containing index n‑1 (zero‑based)              */
    idx_t idx0 = n - 1;
    idx_t r_needed = 0;
    idx_t cum = 0;
    while (cum <= idx0) {
        r_needed++;
        cum += r_needed;
    }
    r_needed--;            /* zero‑based row index                           */

    while (rows <= (size_t)r_needed) {
        size_t cur = rows;  /* next row number (0‑based)                     */

        /* Allocate space for the new row                            */
        grow_rows(rows + 1);
        row_start[rows] = total_elems;

        /* Build the row temporarily                                 */
        static seq_t tmp[2000];        /* large enough for all needed rows          */
        tmp[0] = 1;
        if (cur == 0) {
            /* row 0: only one element                            */
        }
        else if (cur == 1) {
            /* row 1 has elements {1,2}                           */
            tmp[1] = 2;
        }
        else {
            /* row cur≥2                                         */
            tmp[1] = row_sum[cur-1];          /* T(cur,1) = sum(row cur‑1) */
            for (size_t k = 2; k <= cur; ++k) {
                int sign = ((k+1) & 1) ? -1 : 1;  /* (-1)^(k+1)           */
                if (sign == 1)
                    tmp[k] = tmp[k-1] + row_sum[cur - k];
                else
                    tmp[k] = tmp[k-1] - row_sum[cur - k];
            }
        }

        /* Append the row to the flattened array and compute its sum */
        size_t needed = total_elems + cur + 1;
        grow_vals(needed);

        seq_t row_total = 0;
        for (size_t k = 0; k <= cur; ++k) {
            vals[total_elems + k] = tmp[k];
            row_total += tmp[k];
        }

        row_sum[cur] = row_total;
        total_elems += cur + 1;
        rows++;
    }
}

/* ------------------------------------------------------------------ */
/* external entry point                                            */

seq_t a(idx_t n)   /* external linkage */
{
    if (n == 0) return 0;         /* undefined for n<1, safe return          */

    ensure_rows(n);

    idx_t idx0 = n - 1;           /* zero‑based position in flattened array  */

    /* locate the row containing this index                          */
    size_t r = 0;
    while (r < rows) {
        if (idx0 <= row_start[r] + r) break;
        r++;
    }

    idx_t k = idx0 - row_start[r];
    return vals[row_start[r] + k];
}
